{
  "requirement_items": [
    {
      "section": "4.2.3.7.3",
      "label": "[REQ-1-OAD-1430]",
      "text": "Each lower Nasmyth platform shall provide a grid of hard points for attaching instrument support structures.",
      "id": "REQ-1-OAD-1430"
    },
    {
      "section": "4.2.3.7.3",
      "label": "[REQ-1-OAD-1435]",
      "text": "The instrument support structures shall support each instrument in a manner that meets: (1) the image size error budget terms for optical alignment (image jitter and image blur); (2) the pointing error budget; and (3) the pupil shift error budget.",
      "id": "REQ-1-OAD-1435"
    },
    {
      "section": "4.2.3.7.3",
      "label": "[REQ-1-OAD-1440]",
      "text": "The instrument support structures shall also enable access to the instruments for servicing, and shall support auxiliary equipment such as electronics enclosures, as agreed upon in the instrument to telescope interface requirements.",
      "id": "REQ-1-OAD-1440"
    },
    {
      "section": "4.2.3.7.3",
      "label": "[REQ-1-OAD-1450]",
      "text": "The Nasmyth platforms and instrument support structures shall be designed to have minimal obstruction of air flow across the primary mirror.",
      "id": "REQ-1-OAD-1450"
    },
    {
      "section": "4.2.3.7.4",
      "label": "[REQ-1-OAD-1455]",
      "text": "The general services supplied to the Nasmyth Platforms shall be compressed air, coolant and cryogens, utility power, UPS, copper wire and optical fiber for control and communication.",
      "id": "REQ-1-OAD-1455"
    },
    {
      "section": "4.2.3.7.5",
      "label": "[REQ-1-OAD-1460]",
      "text": "All permanent Nasmyth platform levels shall be accessible by personnel and equipment from the elevation of the observatory fixed base floor.",
      "id": "REQ-1-OAD-1460"
    },
    {
      "section": "4.2.3.7.5",
      "label": "[REQ-1-OAD-1461]",
      "text": "Access to and from Nasmyth areas shall not place any requirements on the position or movement of the enclosure system.",
      "id": "REQ-1-OAD-1461"
    },
    {
      "section": "4.2.3.7.5",
      "label": "[REQ-1-OAD-1465]",
      "text": "One or more elevators shall be provided to lift personnel and pieces of equipment up to 1.5 x 1.5 x 1.5 m and 500 kg to the Nasmyth platforms.",
      "id": "REQ-1-OAD-1465"
    },
    {
      "section": "4.2.3.7.5",
      "label": "[REQ-1-OAD-1467]",
      "text": "As a goal, elevator access to and from the Nasmyth areas shall be possible at any or at many telescope azimuth position(s).",
      "id": "REQ-1-OAD-1467"
    },
    {
      "section": "4.2.3.7.5",
      "label": "[REQ-1-OAD-1470]",
      "text": "The elevator shall be attached to the telescope azimuth structure, and the lower level shall be at the azimuth walkway adjacent to the telescope pier.",
      "id": "REQ-1-OAD-1470"
    },
    {
      "section": "4.2.3.7.5",
      "label": "[REQ-1-OAD-1472]",
      "text": "Each Nasmyth platform shall be directly accessible by one or more stairways, that don't require crossing to the other side of the telescope.",
      "id": "REQ-1-OAD-1472"
    },
    {
      "section": "4.2.3.7.5",
      "label": "[REQ-1-OAD-1473]",
      "text": "Stairway access to and from the Nasmyth areas shall be possible at any telescope azimuth position.",
      "id": "REQ-1-OAD-1473"
    },
    {
      "section": "4.2.3.7.5",
      "label": "[REQ-1-OAD-1475]",
      "text": "The enclosure subsystem shall provide a compliment of cranes and / or hoists that are able to reach and reposition loads anywhere within the perimeter of each Nasmyth platform.",
      "id": "REQ-1-OAD-1475"
    },
    {
      "section": "4.2.3.7.5",
      "label": null,
      "text": "The outer radius of the Nasmyth platform shall be defined as the intersection between the 28.5 m stay in radius and the -7 m platform level, which is a radius of 27.6 m.",
      "id": null
    },
    {
      "section": "4.2.3.7.5",
      "label": "[REQ-1-OAD-1476]",
      "text": "The enclosure mounted cranes and hoists shall be able to reposition loads within their entire working volume, including lowering to the observatory floor.",
      "id": "REQ-1-OAD-1476"
    },
    {
      "section": "4.2.3.7.5",
      "label": "[REQ-1-OAD-1480]",
      "text": "Sufficient space shall be provided between instruments to allow access for servicing.",
      "id": "REQ-1-OAD-1480"
    },
    {
      "section": "4.2.3.7.5",
      "label": "[REQ-1-OAD-1482]",
      "text": "All instruments shall provide a pathway at the Nasmyth platform level, at least 1.5 m wide and 2.5 m high, for personnel and equipment to transit between the +Y and -Y ends of the Nasmyth areas.",
      "id": "REQ-1-OAD-1482"
    }
  ],
